/**
 * Assessment templates for the School Assessments Tool.
 *
 * - isc42: ISC-Aligned Walkthrough (DEFAULT; id kept from the original
 *   42-point instrument — the walkthrough now carries 76 checkpoints) — field instrument
 *   transcribed from the 13-domain field walkthrough checklist.
 * - fl-fssat / la: state-style templates modeled on the Florida FSSAT
 *   and Louisiana school safety evaluations (four domains each).
 * - pa / tx / va / ky / tn: state-program templates in
 *   lib/templates-states.ts, built from each state's published
 *   assessment criteria (see that file's header for provenance).
 *
 * Every checkpoint carries an explicit negative `gap` statement so
 * findings derived from a "no" answer never echo the positive
 * criterion wording.
 */

export interface Checkpoint {
  /** Unique within the template, e.g. "1.1", "5.3". */
  key: string;
  /** Display number (source numbering where available). */
  num: string;
  /** Positive criterion the assessor answers YES / NO / N-A to. */
  text: string;
  /** Negative gap statement used when answered NO. */
  gap: string;
  /** Drafted recommendation attached to the finding. */
  rec: string;
}

export interface TemplateDomain {
  id: string;
  name: string;
  checkpoints: Checkpoint[];
}

export interface AssessmentTemplate {
  id: string;
  name: string;
  description: string;
  domains: TemplateDomain[];
}

