/** Look up a template by id; falls back to the default template. */
export function getTemplate(id: string): AssessmentTemplate {
  return TEMPLATES.find((t) => t.id === id) ?? TEMPLATES[0];
}

/** Find a checkpoint (and its domain) by key within a template. */
export function getCheckpoint(
  template: AssessmentTemplate,
  key: string
): { domain: TemplateDomain; checkpoint: Checkpoint } | undefined {
  for (const domain of template.domains) {
    const checkpoint = domain.checkpoints.find((c) => c.key === key);
    if (checkpoint) return { domain, checkpoint };
  }
  return undefined;
}

/** Total checkpoint count for a template. */
export function templateSize(template: AssessmentTemplate): number {
  return template.domains.reduce((n, d) => n + d.checkpoints.length, 0);
}
